using EduCenterManagement.Services;using EduCenterManagement.Services.Common;using Microsoft.AspNetCore.Mvc;namespace EduCenterManagement.Controllers;// TEMP: no authentication yet. Replace QueryStringCurrentUserContext with claims-based implementation and add [Authorize] when auth is merged.
public sealed class StudentTimetableController(ICurrentUserContext current,ITimetableService service):Controller{public async Task<IActionResult> Index(DateOnly? weekStart,CancellationToken ct=default){if(current.UserId is not int id)return View("NoUser");var d=weekStart??DateOnly.FromDateTime(DateTime.Today);var monday=d.AddDays(-((int)d.DayOfWeek+6)%7);var result=await service.GetWeekAsync(id,monday,ct);if(result is null){ ViewData["ProfileMessage"]="This user does not have a Student profile."; return View("NoUser"); } return View(result);}}
